let btBars=[],btPendingBars=null,btResult=null,btMode='research',btCursor=0,btFileLabel='',btMeta=null,btHash='not calculated',btTimer=null,btPaperQueue=[],btSettings={feeBps:1,slippageBps:2};
function backtest(){
  app.innerHTML=`<div class="page-head"><div class="eyebrow">LOCAL RESEARCH · U.S. STOCKS / ETFs</div><h1>Backtesting lab</h1><p>Import your own OHLCV CSV, review its health, replay completed bars, then run a transparent example rule set. No live quotes or orders.</p></div>
  <div class="notice warning"><b>Data source not connected.</b> Yahoo API product, endpoint and authentication are still unidentified. Nothing here is a Yahoo quote. This lab runs on a CSV you provide and keeps raw bars in memory for this browser session only.</div>
  <section class="bt-layout"><div class="bt-main"><div class="card bt-toolbar"><div><label class="tiny" for="btSymbol">SYMBOL</label><input id="btSymbol" maxlength="15" value="${esc(btMeta?.symbol||'SPY')}" aria-label="Instrument symbol"></div><div><label class="tiny" for="btFrame">TIMEFRAME</label><select id="btFrame"><option>1 day</option><option>1 hour</option><option>30 minutes</option><option>15 minutes</option></select></div><div><label class="tiny" for="btZone">CHART TIMEZONE</label><select id="btZone"><option>UTC</option><option>America/New_York</option><option>America/Los_Angeles</option></select></div><div class="bt-mode"><button class="button small ${btMode==='research'?'':'secondary'}" onclick="btSetMode('research')">Research</button><button class="button small ${btMode==='replay'?'':'secondary'}" onclick="btSetMode('replay')">Replay</button></div></div>
  <div class="card chart-card"><div class="chart-title"><div><b>${esc(btMeta?.symbol||'SPY')}</b><span>${btMeta?`${esc(btMeta.assetType)} · ${esc(btMeta.timeframe)} · ${esc(btMeta.timezone)}`:'Import a dataset to begin'}</span></div><span class="pill">${btMode==='replay'?'FUTURE BARS HIDDEN':'FULL SAMPLE'}</span></div><div id="btChart" class="chart-empty">Select a CSV to preview price bars. No sample or historical prices are included.</div><div class="replay-controls"><button class="button secondary small" onclick="btStep(-1)" ${btBars.length?'':'disabled'}>← Step</button><button class="button small" onclick="btPlay()" ${btBars.length?'':'disabled'}>${btTimer?'Pause':'Play'} ▶</button><button class="button secondary small" onclick="btStep(1)" ${btBars.length?'':'disabled'}>Step →</button><input id="btSeek" type="range" min="0" max="${Math.max(0,btBars.length-1)}" value="${Math.min(btCursor,Math.max(0,btBars.length-1))}" oninput="btSeek(this.value)" ${btMode==='replay'&&btBars.length?'':'disabled'} aria-label="Replay bar position"><span>${btBars.length?(btMode==='replay'?`Bar ${btCursor+1}`:`${btCursor+1} / ${btBars.length} bars`):''}</span></div></div>
  ${btMode==='replay'?btPaperPanel():''}
  <div class="card"><div class="row between"><div><h2>Import market data</h2><p>Required: timestamp, open, high, low, close. Volume is optional. Dates without a time are treated as UTC; timestamps with a time must include a timezone offset.</p></div><span class="status neutral">CSV · local</span></div><div class="form-grid bt-import"><div class="field"><label for="btFile">OHLCV CSV</label><input id="btFile" type="file" accept=".csv,text/csv" onchange="btLoadFile(event)"></div><div class="field"><label for="btVenue">Venue</label><input id="btVenue" placeholder="e.g. NASDAQ"></div><div class="field"><label for="btCurrency">Currency</label><select id="btCurrency"><option>USD</option></select></div><div class="field"><label for="btAdjustment">Adjustment policy</label><select id="btAdjustment"><option value="unknown">Unknown / not documented</option><option value="split-adjusted">Split-adjusted</option><option value="unadjusted">Unadjusted</option><option value="total-return">Total-return adjusted</option></select></div><div class="field"><label for="btSource">Provider / source</label><input id="btSource" placeholder="Name of data source"></div><div class="field"><label for="btRights">Usage rights</label><select id="btRights"><option value="unknown">Unknown</option><option value="personal">Personal use confirmed by me</option><option value="public">Public-domain / permitted redistribution</option></select></div></div><div id="btPreview" class="dataset-preview" aria-live="polite"></div></div>
  ${btHealthPanel()}<div id="btResultPanel">${btResultsPanel()}</div>
  <div id="btExperimentPanel" class="card" ${btMode==='replay'?'hidden':''}><div class="row between"><div><h2>Experiment history</h2><p>Each run records the rule version and settings. Viewing the holdout consumes it; changing settings afterward does not create a fresh untouched test.</p></div><span class="status ${state.testConsumed?'waiting':'neutral'}">${state.testConsumed?'Holdout viewed':'No test run yet'}</span></div>${state.experiments?.length?`<div class="table-wrap"><table><thead><tr><th>Version</th><th>Date</th><th>Rule</th><th>Bars</th><th>Net P/L</th><th>Normalized-data SHA-256</th></tr></thead><tbody>${state.experiments.slice().reverse().map(x=>`<tr><td>${esc(x.version)}</td><td>${esc(x.date)}</td><td>${esc(x.rule)}</td><td>${esc(x.bars)}</td><td>${cash(x.netPnl)}</td><td><code>${esc((x.hash||'n/a').slice(0,16))}</code></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No experiments yet.</div>'}</div></div>
  <aside class="bt-side"><div class="card"><div class="eyebrow">WATCHLIST</div><div class="watch-row"><b>SPY</b><span>—</span></div><div class="watch-row"><b>QQQ</b><span>—</span></div><div class="watch-row"><b>IWM</b><span>—</span></div><small class="muted">Quotes are not connected. Add your own symbol and CSV; dashes are unavailable data, not zero prices.</small></div><div class="card"><div class="eyebrow">INSTRUMENT DETAILS</div><dl class="detail-list"><dt>Asset</dt><dd>U.S. stock / ETF</dd><dt>Price unit</dt><dd>USD per share</dd><dt>Quantity</dt><dd>Fractional shares in simulation</dd><dt>Corporate actions</dt><dd>Not modeled</dd><dt>Shorting</dt><dd>Blocked</dd></dl></div><div class="card"><div class="eyebrow">SUPPORT STATUS</div><div class="support-line"><b>Stocks / ETFs</b><span class="status neutral">Data-dependent</span></div><div class="support-line"><b>Spot crypto</b><span class="status waiting">Not implemented</span></div><div class="support-line"><b>Options · bonds · futures · perpetuals · forex</b><span class="status waiting">Blocked</span></div><p class="tiny">See README for payoff, units, quantity, margin and event-handling limits by asset.</p></div></aside></section>`;
  renderBtChart();
}
function btHealthPanel(){if(!btMeta)return '';const replay=btMode==='replay',current=btBars[Math.min(btCursor,btBars.length-1)];return `<div class="card"><div class="row between"><div><h2>Dataset health</h2><p>Validation is limited to required CSV fields and candle integrity; provider provenance is not certified.</p></div><span class="status neutral">${replay?`Replay bar ${btCursor+1}`:`${btMeta.bars} bars`}</span></div><div class="split-grid"><div class="split-cell"><b>Coverage</b><span>${esc(btMeta.start)} → ${replay?`${current?new Date(current.time).toISOString():'—'} · future span hidden`:esc(btMeta.end)}</span></div><div class="split-cell"><b>Source / venue</b><span>${esc(btMeta.provider)} · ${esc(btMeta.venue)}</span></div><div class="split-cell"><b>OHLC integrity</b><span>Valid; sorted; duplicate timestamps rejected</span></div><div class="split-cell"><b>Volume</b><span>${btMeta.missingVolume?'Missing or partial — not invented':'Present in all bars'}</span></div><div class="split-cell"><b>Intraday gaps</b><span>${replay?'Full-sample gap report hidden':btMeta.candidateIntradayGaps===null?'Not assessed for daily data':`${btMeta.candidateIntradayGaps} candidate gaps; calendar / holidays not modeled`}</span></div><div class="split-cell"><b>Adjustment / rights</b><span>${esc(btMeta.adjustment)} · ${esc(btMeta.usageRights)}</span></div></div><p class="tiny">Corporate actions, point-in-time universe, delistings, splits and dividends are not modeled. Adjustment status is user-supplied. If usage rights are unknown, use only data you are authorized to process. No data is sent externally.</p></div>`}
function btPaperSnapshot(atTime=Infinity,markPrice=null,symbol=btMeta?.symbol){let cash=+(state.btPaperStartingEquity||10000),positions={},realized=0;for(const t of (state.btPaperOrders||[]).filter(x=>x.status==='filled'&&x.executionTime<=atTime)){let p=positions[t.symbol]||{qty:0,avg:0};if(t.side==='buy'){p.avg=p.qty?(p.avg*p.qty+t.price*t.qty+t.fee)/(p.qty+t.qty):(t.price+t.fee/t.qty);p.qty+=t.qty;cash-=t.price*t.qty+t.fee}else{realized+=t.qty*(t.price-p.avg)-t.fee;p.qty-=t.qty;cash+=t.price*t.qty-t.fee;if(p.qty<1e-9){p.qty=0;p.avg=0}}positions[t.symbol]=p}const p=positions[symbol]||{qty:0,avg:0};return {cash,positions,position:p,realized,equity:cash+Object.entries(positions).reduce((s,[sym,x])=>s+x.qty*(sym===symbol&&markPrice!==null?markPrice:x.avg),0)}}
function btPaperPanel(){if(!btBars.length)return '';const bar=btBars[Math.max(0,Math.min(btCursor,btBars.length-1))],snapshot=btPaperSnapshot(bar.time,bar.c),hasFuture=btBars.slice(0,btCursor+1).some(x=>(state.btPaperOrders||[]).some(t=>t.executionTime>x.time)),queued=btPaperQueue.filter(x=>!x.processed&&x.signalTime<=bar.time),futureOrders=(state.btPaperOrders||[]).filter(x=>x.executionTime>bar.time);return `<div class="card"><div class="row between"><div><div class="eyebrow">REPLAY PAPER TRADING · LOCAL LEDGER</div><h2>Practice buy / sell</h2><p>Paper orders queue after the visible completed bar and use the next bar open with adverse slippage. No broker is connected. These orders are separate from backtest results.</p></div><span class="status neutral">${btMeta?.symbol||'—'} · ${new Date(bar.time).toISOString()}</span></div><div class="form-grid"><div class="field"><label for="btPaperEquity">Starting practice equity (USD)</label><input id="btPaperEquity" type="number" min="1" value="${esc(state.btPaperStartingEquity||10000)}" ${state.btPaperOrders?.some(x=>x.status==='filled')?'disabled':''}></div><div class="field"><label for="btPaperQty">Order quantity (fractional shares)</label><input id="btPaperQty" type="number" min="0.0001" step="0.0001" value="1"></div><div class="field"><label>Visible completed-bar close</label><input value="${cash(bar.c)}" disabled></div></div><div class="actions"><button class="button" onclick="btQueuePaper('buy')" ${btCursor>=btBars.length-1||hasFuture?'disabled':''}>Queue paper buy</button><button class="button secondary" onclick="btQueuePaper('sell')" ${btCursor>=btBars.length-1||hasFuture?'disabled':''}>Queue paper sell</button><button class="button secondary small" onclick="btExportPaper()" ${(state.btPaperOrders||[]).length?'':'disabled'}>Export paper ledger</button><button class="button secondary small" onclick="btResetPaper()">Reset practice account</button><span class="tiny">Cash ${cash(snapshot.cash)} · ${esc(btMeta?.symbol||'')} shares ${fmt(snapshot.position.qty,4)} · avg cost ${cash(snapshot.position.avg)} · unrealized ${cash(snapshot.position.qty*(bar.c-snapshot.position.avg))}</span></div>${queued.map(x=>`<div class="notice">${esc(x.side.toUpperCase())} ${fmt(x.qty,4)} queued · it will not fill until you reveal the next bar. <button class="button secondary small" onclick="btCancelPaper('${esc(x.id)}')">Cancel</button></div>`).join('')}${hasFuture||futureOrders.length?'<div class="notice warning">This replay cursor is before previously revealed paper fills. Their later ledger rows are hidden; return to the latest revealed bar before placing new orders.</div>':''}<h3>Revealed paper fills</h3>${(state.btPaperOrders||[]).filter(x=>x.status==='filled'&&x.executionTime<=bar.time).length?`<div class="table-wrap"><table><thead><tr><th>Side</th><th>Signal time</th><th>Fill time</th><th>Qty</th><th>Fill</th><th>Fees</th><th>Position after</th></tr></thead><tbody>${(state.btPaperOrders||[]).filter(x=>x.status==='filled'&&x.executionTime<=bar.time).map(x=>`<tr><td>${esc(x.side)}</td><td>${new Date(x.signalTime).toISOString()}</td><td>${new Date(x.executionTime).toISOString()}</td><td>${fmt(x.qty,4)}</td><td>${cash(x.price)}</td><td>${cash(x.fee)}</td><td>${fmt(x.positionAfter,4)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No paper fills have been revealed.</div>'}</div>`}
function btSavePracticeEquity(){const input=$('#btPaperEquity');if(!input||state.btPaperOrders?.some(x=>x.status==='filled'))return true;const n=+input.value;if(!Number.isFinite(n)||n<=0){toast('Starting equity must be positive');return false}state.btPaperStartingEquity=n;save();return true}
function btQueuePaper(side){if(!btSavePracticeEquity())return;const q=+$('#btPaperQty')?.value,bar=btBars[btCursor];if(btBars.slice(0,btCursor+1).some(x=>(state.btPaperOrders||[]).some(t=>t.executionTime>x.time))){toast('Return to the latest revealed bar before placing a paper order');return}if(!bar||btCursor>=btBars.length-1){toast('No next bar is available to fill this order');return}if(!Number.isFinite(q)||q<=0){toast('Quantity must be positive');return}btPaperQueue.push({id:`${Date.now()}-${Math.random()}`,side,symbol:btMeta.symbol,qty:q,signalTime:bar.time,targetIndex:btCursor+1,dataset:btMeta.file,processed:false});backtest();toast(`${side.toUpperCase()} queued for the next bar open`)}
function btProcessPaperQueue(){if(btMode!=='replay'||!btBars[btCursor])return;const bar=btBars[btCursor],pending=btPaperQueue.filter(x=>!x.processed&&x.targetIndex<=btCursor&&x.signalTime<bar.time);if(!pending.length)return;for(const o of pending){const slip=btSettings.slippageBps/10000,feeBps=btSettings.feeBps,price=bar.o*(o.side==='buy'?1+slip:1-slip),fee=price*o.qty*feeBps/10000,s=btPaperSnapshot(bar.time,bar.c,o.symbol),p=s.positions[o.symbol]||{qty:0,avg:0};let status='filled',reason='';if(o.side==='buy'&&price*o.qty+fee>s.cash){status='rejected';reason='Insufficient practice cash at next-bar open'}if(o.side==='sell'&&o.qty>p.qty+1e-9){status='rejected';reason='Sell quantity exceeds long practice position'}let positionAfter=p.qty;if(status==='filled'){if(o.side==='buy')positionAfter+=o.qty;else positionAfter-=o.qty}state.btPaperOrders=state.btPaperOrders||[];state.btPaperOrders.push({...o,processed:undefined,price,fee,executionTime:bar.time,status,reason,positionAfter,referenceOpen:bar.o});o.processed=true;toast(status==='filled'?`Paper ${o.side} filled at next-bar open`:reason)}save()}
function btExportPaper(){const rows=[['status','side','symbol','signal_time_utc','fill_time_utc','quantity','fill_price','reference_open','fee','position_after','reason'],...(state.btPaperOrders||[]).map(x=>[x.status,x.side,x.symbol,new Date(x.signalTime).toISOString(),new Date(x.executionTime).toISOString(),x.qty,x.price,x.referenceOpen,x.fee,x.positionAfter,x.reason])];download(new Blob([BacktestEngine.csv(rows)],{type:'text/csv;charset=utf-8'}),`${btMeta?.symbol||'paper'}-replay-practice-ledger.csv`)}
function btResetPaper(){if(!confirm('Reset the local replay paper account and delete its recoverable practice ledger? This does not affect live accounts.'))return;state.btPaperOrders=[];state.btPaperStartingEquity=10000;btPaperQueue=[];save();backtest()}
function btResultsPanel(){if(btMode==='replay')return `<div class="card"><h2>Replay mode</h2><p>Full-sample results and future trades are hidden while replay is active. Step through completed bars above. Switch back to Research to view the whole sample.</p></div>`;if(!btResult)return `<div class="card"><h2>Rule and assumptions</h2><p>Educational example: long-only close crossing above a ${esc($('#btSma')?.value||5)}-bar simple moving average enters at the next bar open; a cross below exits at the next bar open. One position at a time. No stop, shorting, dividends, corporate actions, borrow, partial fills or intrabar inference.</p><div class="form-grid"><div class="field"><label for="btSma">SMA lookback (bars)</label><input id="btSma" type="number" min="2" max="250" value="5"></div><div class="field"><label for="btAlloc">Allocation (% equity)</label><input id="btAlloc" type="number" min="1" max="100" value="25"></div><div class="field"><label for="btEquity">Starting paper equity (USD)</label><input id="btEquity" type="number" min="1" value="10000"></div><div class="field"><label for="btFees">Fees (basis points / side)</label><input id="btFees" type="number" min="0" step="0.1" value="1"></div><div class="field"><label for="btSlip">Slippage (basis points / side)</label><input id="btSlip" type="number" min="0" step="0.1" value="2"></div></div><div class="actions"><button class="button" onclick="btRun()" ${btBars.length?'':'disabled'}>Run once · create experiment</button><span class="tiny">One explicit configuration. No parameter optimization.</span></div></div>`;
  const r=btResult,wins=r.trades.filter(t=>t.netPnl>0),losses=r.trades.filter(t=>t.netPnl<0),avg=x=>x.length?x.reduce((a,t)=>a+t.netPnl,0)/x.length:null,metrics=[['Gross P/L',cash(r.trades.reduce((a,t)=>a+t.grossPnl,0))],['Net P/L',cash(r.netPnl)],['Final equity',cash(r.finalEquity)],['Max drawdown',`${(r.maxDrawdown*100).toFixed(2)}%`],['Closed trades',String(r.trades.length)],['Win rate',r.winRate===null?'—':`${(r.winRate*100).toFixed(1)}%`],['Avg win / loss',`${avg(wins)===null?'—':cash(avg(wins))} / ${avg(losses)===null?'—':cash(avg(losses))}`],['Expectancy',r.expectancy===null?'—':cash(r.expectancy)],['Profit factor',r.profitFactor===null?'Undefined':r.profitFactor.toFixed(2)],['Fees (closed)',cash(r.trades.reduce((a,t)=>a+t.fees,0))],['Buy & hold benchmark',cash(r.benchmarkPnl)],['2× fees + slippage',cash(r.worseCostPnl)],['Open unrealized',cash(r.unrealizedPnl)]];
  return `<div class="card"><div class="row between"><div><h2>Results · ${esc(btMeta?.symbol||'')}</h2><p>Same-session local run · ${r.barsCount} bars · SMA ${r.smaLength} · ${r.allocationPct}% notional allocation · next-bar open fills</p></div><div class="actions"><button class="button secondary small" onclick="btExport('trades')">Export trade ledger</button><button class="button secondary small" onclick="btExport('bundle')">Export reproducibility JSON</button></div></div><h3>Execution assumptions</h3><div class="split-grid"><div class="split-cell"><b>Starting equity</b><span>${cash(r.startEquity)} USD</span></div><div class="split-cell"><b>Size</b><span>${r.allocationPct}% of current cash; fractional long shares</span></div><div class="split-cell"><b>Costs</b><span>${r.feeBps} bps fees + ${r.slippageBps} bps adverse slippage per side</span></div><div class="split-cell"><b>Entry / exit</b><span>Signal at completed close; fill next bar open</span></div><div class="split-cell"><b>Price adjustment</b><span>${esc(btMeta?.adjustment||'Unknown; user supplied')}</span></div><div class="split-cell"><b>Currency / timezone</b><span>${esc(btMeta?.currency||'USD')} · timestamps normalized to UTC</span></div></div><div class="result-grid">${metrics.map(m=>`<div class="card"><div class="metric">${m[1]}</div><div class="metric-label">${m[0]}</div></div>`).join('')}</div><div class="grid grid-2 bt-plots"><div class="card"><h3>Equity curve · marked to close</h3>${btLineSvg(r.equity.map(p=>p.value),'equity')}</div><div class="card"><h3>Drawdown from prior peak</h3>${btLineSvg(btDrawdowns(r.equity),'drawdown')}</div></div><div class="notice warning"><b>Research limits:</b> This is a basic SMA crossover example, not a recommendation. The test uses the full uploaded sample. No split/dividend adjustment, delisted names, point-in-time universe, taxes, market-hours/session controls, spread-specific quotes, tick/lot rounding, order rejection, volume constraints or historical bid/ask. Results are sensitive to data quality and the declared fee/slippage inputs. First run marks any viewed holdout as consumed; a fresh future period is needed for another untouched test.</div>${btSplitReport(r)}<h3>Trade ledger</h3>${r.trades.length?`<div class="table-wrap"><table><thead><tr><th>Entry time</th><th>Exit time</th><th>Qty</th><th>Entry fill</th><th>Exit fill</th><th>Gross P/L</th><th>Costs</th><th>Net P/L</th><th>Bars</th></tr></thead><tbody>${r.trades.map(t=>`<tr><td>${new Date(t.entryTime).toISOString()}</td><td>${new Date(t.exitTime).toISOString()}</td><td>${fmt(t.quantity,4)}</td><td>${cash(t.entryPrice)}</td><td>${cash(t.exitPrice)}</td><td>${cash(t.grossPnl)}</td><td>${cash(t.fees)}</td><td>${cash(t.netPnl)}</td><td>${t.barsHeld}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No closed trades occurred under this rule. No performance conclusion can be drawn from zero trades.</div>'}</div>`}
function btDrawdowns(points){let peak=points[0]?.value||1;return points.map(p=>{peak=Math.max(peak,p.value);return (peak-p.value)/peak})}
function btLineSvg(values,kind){if(!values.length)return '';const W=600,H=170,pad=8,min=Math.min(...values),max=Math.max(...values),span=max-min||1,path=values.map((v,i)=>`${i?'L':'M'}${pad+i*(W-pad*2)/Math.max(1,values.length-1)},${H-pad-(v-min)/span*(H-pad*2)}`).join(' ');return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${kind} chart"><line x1="0" x2="${W}" y1="${H-pad}" y2="${H-pad}" class="chart-axis"/><path d="${path}" fill="none" stroke="var(--ink)" stroke-width="2"/><text x="8" y="14" class="chart-label">${fmt(max,2)}</text><text x="8" y="${H-12}" class="chart-label">${fmt(min,2)}</text></svg>`}
function btSplitReport(r){const cuts=[Math.floor(btBars.length*.6),Math.floor(btBars.length*.8)],parts=[btBars.slice(0,cuts[0]),btBars.slice(cuts[0],cuts[1]),btBars.slice(cuts[1])],names=['Development 60%','Validation 20%','Untouched test 20%'];return `<h3>Chronological partitions</h3><div class="split-grid">${parts.map((p,i)=>{let v='Not enough bars for this rule';if(p.length>=r.smaLength+2){try{const x=BacktestEngine.run({bars:p,smaLength:r.smaLength,startEquity:r.startEquity,allocationPct:r.allocationPct,feeBps:r.feeBps,slippageBps:r.slippageBps});v=`${p.length} bars · ${x.trades.length} trades · ${cash(x.netPnl)}`}catch{}}return `<div class="split-cell"><b>${names[i]}</b><span>${v}</span>${i===2&&state.testConsumed?'<small>Consumed on first result view</small>':''}</div>`}).join('')}</div><p class="tiny">Each partition starts with a fresh account and its own indicator warmup. These are coarse exploratory partitions, not a statistical certification. Revising settings after seeing results makes the holdout consumed.</p>`}
function btLoadFile(e){const f=e.target.files?.[0];if(!f)return;if(f.size>15*1024*1024){$('#btPreview').innerHTML='<div class="notice warning">File exceeds the 15 MB limit.</div>';return}const rd=new FileReader();rd.onload=()=>{try{btPendingBars=MarketDataProviders.load('user-csv',String(rd.result));btFileLabel=f.name;$('#btPreview').innerHTML=`<div class="notice"><b>Preview ready:</b> ${btPendingBars.length} bars · ${new Date(btPendingBars[0].time).toISOString()} to ${new Date(btPendingBars.at(-1).time).toISOString()} · volume ${btPendingBars.every(b=>b.v!==null)?'present':'missing'}. Sorted chronologically; invalid OHLC and duplicates are rejected. <button class="button small" onclick="btAcceptDataset()">Use this dataset</button></div><div class="table-wrap"><table><thead><tr><th>Timestamp</th><th>Open</th><th>High</th><th>Low</th><th>Close</th><th>Volume</th></tr></thead><tbody>${btPendingBars.slice(0,5).map(b=>`<tr><td>${new Date(b.time).toISOString()}</td><td>${b.o}</td><td>${b.h}</td><td>${b.l}</td><td>${b.c}</td><td>${b.v??'—'}</td></tr>`).join('')}</tbody></table></div>`}catch(err){btPendingBars=null;$('#btPreview').innerHTML=`<div class="notice warning">${esc(err.message)}</div>`}};rd.readAsText(f)}
async function btAcceptDataset(){if(!btPendingBars?.length)return;const symbol=$('#btSymbol').value.trim().toUpperCase();if(!/^[A-Z0-9.^=-]{1,15}$/.test(symbol)){toast('Enter a valid stock / ETF symbol');return}if(btPendingBars.some(b=>[b.o,b.h,b.l,b.c].some(x=>x<=0))){$('#btPreview').insertAdjacentHTML('afterbegin','<div class="notice warning">This stocks / ETFs adapter requires positive USD share prices. Negative-price instruments are not supported by this adapter.</div>');return}if(!confirm(`Replace the in-memory dataset with ${btPendingBars.length} bars for ${symbol}? This does not upload or send data.`))return;btBars=btPendingBars;btPendingBars=null;btPaperQueue=[];btResult=null;btCursor=0;btMode='research';const frame=$('#btFrame').value,expected={'1 hour':3600000,'30 minutes':1800000,'15 minutes':900000}[frame];let gapCount=expected?btBars.slice(1).filter((b,i)=>b.time-btBars[i].time>expected*1.5).length:null;btMeta={symbol,assetType:'U.S. stock / ETF',venue:$('#btVenue').value||'Unknown',currency:$('#btCurrency').value,timeframe:frame,timezone:$('#btZone').value,provider:$('#btSource').value||'User supplied CSV; source unknown',file:btFileLabel,adjustment:$('#btAdjustment').value,usageRights:$('#btRights').value,retrievedAt:new Date().toISOString(),start:new Date(btBars[0].time).toISOString(),end:new Date(btBars.at(-1).time).toISOString(),bars:btBars.length,missingVolume:btBars.some(b=>b.v===null),candidateIntradayGaps:gapCount,notes:'Raw data held in memory only; source, adjustment, usage rights, corporate actions and calendar remain user-attested or unknown.'};state.datasetMeta=btMeta;save();backtest();toast('Dataset loaded for this session')}
function renderBtChart(){const host=$('#btChart');if(!host)return;if(!btBars.length){host.innerHTML='Select a CSV to preview price bars. No sample or historical prices are included.';host.classList.add('chart-empty');return}host.classList.remove('chart-empty');const visible=btMode==='replay'?btBars.slice(0,Math.max(1,btCursor+1)):btBars.slice(-100),W=920,H=330,top=16,bottom=286,vals=visible.flatMap(b=>[b.h,b.l]),min=Math.min(...vals),max=Math.max(...vals),span=max-min||1,step=W/visible.length,vol=visible.some(b=>b.v!==null),y=p=>top+(max-p)/span*(bottom-top),candleW=Math.max(2,Math.min(12,step*.6));let marks=visible.map((b,i)=>{let x=i*step+step/2,color=b.c>=b.o?'var(--chart-up)':'var(--chart-down)',bodyY=Math.min(y(b.o),y(b.c)),bodyH=Math.max(1,Math.abs(y(b.c)-y(b.o)));return `<g><line x1="${x}" x2="${x}" y1="${y(b.h)}" y2="${y(b.l)}" stroke="${color}"/><rect x="${x-candleW/2}" y="${bodyY}" width="${candleW}" height="${bodyH}" fill="${color}"/></g>`}).join('');let volumes=vol?visible.map((b,i)=>b.v===null?'':`<rect x="${i*step+step*.25}" y="${bottom+20}" width="${Math.max(1,step*.5)}" height="${Math.min(26,(b.v/(Math.max(...visible.map(x=>x.v||0))||1))*26)}" fill="var(--chart-volume)"/>`).join(''):'';host.innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${btMode==='replay'?'Replay-visible':'Research'} candlestick chart with ${visible.length} bars"><line x1="0" x2="${W}" y1="${bottom}" y2="${bottom}" class="chart-axis"/><text x="6" y="13" class="chart-label">${fmt(max,2)}</text><text x="6" y="${bottom-4}" class="chart-label">${fmt(min,2)}</text>${marks}${volumes}<text x="8" y="${H-5}" class="chart-label">${new Date(visible[0].time).toISOString().slice(0,10)}</text><text x="${W-110}" y="${H-5}" class="chart-label">${new Date(visible.at(-1).time).toISOString().slice(0,10)}</text></svg>`}
function btCancelQueuedFrom(time){const pending=btPaperQueue.filter(o=>!o.processed&&o.signalTime>time);if(!pending.length)return true;if(!confirm('Moving before the signal bars will cancel the pending paper orders. Continue?'))return false;btPaperQueue=btPaperQueue.filter(o=>!pending.includes(o));return true}
function btCancelPaper(id){btPaperQueue=btPaperQueue.filter(x=>x.id!==id);backtest()}
function btSetMode(x){if(btTimer){clearInterval(btTimer);btTimer=null}btMode=x;if(x==='replay')btCursor=0;backtest()}
function btStep(n){if(!btBars.length)return;const target=Math.max(0,Math.min(btBars.length-1,btCursor+n));if(target<btCursor&&!btCancelQueuedFrom(btBars[target].time))return;btMode='replay';btCursor=target;btProcessPaperQueue();backtest()}
function btSeek(n){if(!btBars.length)return;const target=Math.max(0,Math.min(btBars.length-1,+n||0));if(target<btCursor&&!btCancelQueuedFrom(btBars[target].time))return;btMode='replay';btCursor=target;btProcessPaperQueue();backtest()}
function btPlay(){if(btTimer){clearInterval(btTimer);btTimer=null;backtest();return}btMode='replay';btTimer=setInterval(()=>{if(btCursor>=btBars.length-1){clearInterval(btTimer);btTimer=null;backtest();return}btCursor++;btProcessPaperQueue();backtest()},500);backtest()}
async function btRun(){if(!btBars.length||!btMeta){toast('Import and accept a CSV first');return}if(btMode==='replay'){toast('Switch to Research mode to run the full sample');return}const spec={smaLength:+($('#btSma')?.value||5),startEquity:+($('#btEquity')?.value||10000),allocationPct:+($('#btAlloc')?.value||25),feeBps:+($('#btFees')?.value||1),slippageBps:+($('#btSlip')?.value||2)};try{btSettings={feeBps:spec.feeBps,slippageBps:spec.slippageBps};btResult=BacktestEngine.run({bars:btBars,...spec});btResult.worseCostPnl=BacktestEngine.run({bars:btBars,...spec,feeBps:spec.feeBps*2,slippageBps:spec.slippageBps*2}).netPnl;if(window.crypto?.subtle){const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(btBars)));btHash=[...new Uint8Array(buf)].map(x=>x.toString(16).padStart(2,'0')).join('')}else btHash='SHA-256 unavailable';state.testConsumed=true;state.experiments=state.experiments||[];state.experiments.push({version:`SMA-v1.${state.experiments.length}`,date:new Date().toISOString(),rule:`Close crosses SMA(${spec.smaLength}); next-bar open`,bars:btBars.length,netPnl:btResult.netPnl,hash:btHash,metadata:btMeta,settings:spec});save();backtest();toast('Run recorded. Holdout is now consumed.')}catch(err){toast(err.message)}}
