function assistant(){const modes=['Learn','Practice','Research','Strategy Critic','Backtest Explainer','General Study'];app.innerHTML=`<div class="page-head"><div class="eyebrow">TRADING-FOCUSED · PROVIDER NOT CONFIGURED</div><h1>Learning assist</h1><p>AI is not connected. This page does not imitate a live model. Course lookup below searches the supplied Part 1 text locally and shows matching excerpts.</p></div><div class="notice warning"><b>No AI provider configured.</b> No external request or paid service is active. Provider credentials must remain server-side; enabling a provider requires explicit setup and a disclosure of what leaves this browser.</div><div class="card"><label for="assistMode">Mode</label><select id="assistMode">${modes.map(x=>`<option>${x}</option>`).join('')}</select><label for="assistLesson">Link question to lesson</label><select id="assistLesson">${[1,2,3,4].map(n=>`<option value="${n}" ${n===state.lesson?'selected':''}>Part 1 · Lesson ${n}</option>`).join('')}</select><label for="assistQ" class="section-title">Ask or save a question</label><textarea id="assistQ" class="search" placeholder="What part of the lesson is confusing? This question is saved locally only if you choose Save."></textarea><div class="actions"><button class="button" onclick="saveAssistQuestion()">Save to questions</button><button class="button secondary" onclick="lookupCourse()">Search Part 1 locally</button></div><div id="assistResults"></div></div><div class="card"><h2>Approved-source boundary</h2><p>Local lookup can quote matching lines from Part 1. It cannot verify external claims, inspect video visuals, or provide personalized trading advice. Use the resource library for linked sources and their review status.</p><div>${(state.savedQuestions||[]).slice(-8).reverse().map((q,i)=>`<div class="watch-row"><span>${esc(q.text)}<small>Lesson ${q.lesson||'—'} · review ${q.due||'not scheduled'}</small></span><button class="button secondary small" onclick="markQuestionReviewed(${state.savedQuestions.length-1-i})">Reviewed</button><button class="button secondary small" onclick="deleteSavedQuestion(${state.savedQuestions.length-1-i})">Remove</button></div>`).join('')||'<div class="empty">No saved questions.</div>'}</div></div><div class="card"><h2>Personal memory (optional)</h2><p>This note is stored in this browser and is not sent anywhere. It is not used by an AI provider while none is configured.</p><textarea id="memoryNote" maxlength="2000">${esc(state.assistantMemory?.[0]||'')}</textarea><div class="actions"><button class="button secondary" onclick="saveAssistantMemory()">Save memory</button><button class="button secondary" onclick="deleteAssistantMemory()">Delete memory</button></div></div>`}
function lookupCourse(){const q=$('#assistQ').value.trim().toLowerCase();if(!q){$('#assistResults').innerHTML='<p class="notice">Enter a term or question to search the supplied lesson text.</p>';return}const matches=courseText.split('\n').map((line,i)=>({line,i})).filter(x=>x.line.toLowerCase().includes(q)).slice(0,12);$('#assistResults').innerHTML=matches.length?`<h3>Local course matches</h3>${matches.map(x=>`<p class="source-match">${esc(x.line.replace(/^#+\s*/,''))}<small>Course Part 1 · source line ${x.i+1}</small></p>`).join('')}`:'<p class="notice">No exact text match in Part 1. Try a key term. This search did not consult an AI model or external sources.</p>'}
function saveAssistQuestion(){const text=$('#assistQ').value.trim();if(!text)return;state.savedQuestions=state.savedQuestions||[];state.savedQuestions.push({text,mode:$('#assistMode').value,lesson:+$('#assistLesson').value,date:new Date().toISOString(),due:new Date(Date.now()+3*86400000).toISOString().slice(0,10)});save();assistant();toast('Question saved locally')}
