function misconceptions(){state.misconceptions=state.misconceptions||[];app.innerHTML=`<div class="page-head"><div class="eyebrow">PERSONAL REVIEW · LOCAL ONLY</div><h1>Misconception notebook</h1><p>Track ideas that were hard to separate, then revisit them. Notes are user-written and do not become course answers.</p></div><div class="card"><form id="misForm" class="form-grid"><div class="field"><label>Concept</label><input name="concept" required placeholder="e.g. margin vs notional"></div><div class="field"><label>Review again on</label><input name="due" type="date"></div><div class="field full"><label>What I mixed up / corrected explanation</label><textarea name="note" required></textarea></div><div class="field full"><button class="button">Save misconception</button></div></form></div><div class="grid grid-2">${state.misconceptions.map((x,i)=>`<div class="card"><span class="pill">${x.due&&x.due<=new Date().toISOString().slice(0,10)?'DUE TO REVIEW':'SAVED'}</span><h3>${esc(x.concept)}</h3><p>${esc(x.note)}</p><small class="muted">${esc(x.date||'')}</small><div class="actions"><button class="button secondary small" onclick="deleteMisconception(${i})">Delete</button></div></div>`).join('')||'<div class="card empty">No review notes yet.</div>'}</div>`;$('#misForm').onsubmit=e=>{e.preventDefault();state.misconceptions.push({...Object.fromEntries(new FormData(e.target)),date:new Date().toISOString()});save();misconceptions()}}
