function inbox(){state.researchInbox=state.researchInbox||[];app.innerHTML=`<div class="page-head"><div class="eyebrow">IDEA CAPTURE · NO AUTO-PROMOTION</div><h1>Research inbox</h1><p>Capture a claim and its source. An idea is not a strategy specification; “testable” does not mean profitable. No social feed is scraped.</p></div><div class="card"><form id="inboxForm" class="form-grid"><div class="field"><label>Creator / source</label><input name="creator" required></div><div class="field"><label>Original URL</label><input name="url" type="url" placeholder="https://" required></div><div class="field full"><label>Claim as presented</label><textarea name="claim" required></textarea></div><div class="field full"><label>Accessible text or notes (user supplied)</label><textarea name="excerpt" placeholder="Paste only text you have rights to use; mark as incomplete when needed."></textarea></div><div class="field full"><label>Observable rules as stated</label><textarea name="rules" placeholder="Entry, exit, sizing and no-trade rules; leave unknown items blank."></textarea></div><div class="field"><label>Ambiguous or missing rules</label><textarea name="ambiguities" placeholder="What needs clarification?"></textarea></div><div class="field"><label>Claimed mechanism</label><textarea name="mechanism" placeholder="Separate the creator's explanation from observable rules."></textarea></div><div class="field"><label>Evidence they supplied</label><input name="evidence" placeholder="Not independently verified"></div><div class="field"><label>Commercial incentive / referral</label><input name="incentive" placeholder="Unknown"></div><div class="field"><label>Status</label><select name="status"><option>unreviewed</option><option>needs clarification</option><option>testable</option><option>tested</option><option>rejected</option></select></div><div class="field"><label>Required data</label><input name="requiredData" placeholder="Instrument, venue, timeframe, costs…"></div><div class="field"><label>Likely execution difficulties</label><input name="execution" placeholder="Spread, liquidity, order handling…"></div><div class="field full"><label>Other missing information</label><input name="missing" placeholder="Unknown factors and questions for the creator"></div><div class="field full"><button class="button">Save idea</button></div></form></div><div class="grid grid-2">${state.researchInbox.map((x,i)=>`<article class="card"><div class="row between"><span class="status neutral">${esc(x.status)}</span><button class="button secondary small" onclick="deleteInboxItem(${i})">Delete</button></div><h3>${esc(x.creator)}</h3><p><b>Claim:</b> ${esc(x.claim)}</p><p>${esc(x.excerpt||'No source text captured.')}</p><p><b>Observable rules:</b> ${esc(x.rules||'Not stated')} · <b>Ambiguities:</b> ${esc(x.ambiguities||'Not recorded')}</p><p><b>Claimed mechanism:</b> ${esc(x.mechanism||'Not stated')}</p><p class="tiny">Evidence: ${esc(x.evidence||'Unknown')} · Incentive: ${esc(x.incentive||'Unknown')} · Data: ${esc(x.requiredData||'Unknown')} · Execution: ${esc(x.execution||'Unknown')} · Other gaps: ${esc(x.missing||'Not recorded')}</p><a target="_blank" rel="noopener" href="${esc(x.url)}">Open source ↗</a><small class="muted">Captured ${esc(x.date)} · ${esc(x.captureType)}</small></article>`).join('')||'<div class="card empty">Inbox empty. No public page or social account is accessed automatically.</div>'}</div>`;$('#inboxForm').onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));if(!/^https?:\/\//i.test(x.url)){toast('Use an http or https source link');return}state.researchInbox.unshift({...x,date:new Date().toISOString(),captureType:x.excerpt?'User-provided text (not independently verified)':'Link captured; page not accessed'});save();inbox()}}
function deleteInboxItem(i){state.researchInbox.splice(i,1);save();inbox()}
